/* ═══════════════════════════════════════════════════════════════════════════
   bf-12：练手局（practice）

   用户实测：「好感必须 20~79 且当天没送过，否则 9 张卡全灰」→ 根本没法试玩。
   修法分两层：
     · 规则层（本文件守）：finish() 把 bondDelta 归零、结果打 practice 标、
       impact / quota 换成练手局口径；
     · 页面 glue（tools/e2e/bf.js 模式 A 在真 Chrome 里守）：bfApplyResult 见到 practice
       就跳过 好感 / S.breakfastDay / bfWin / 成就 —— 那才拿得到 window.__cs2.S。
   ═══════════════════════════════════════════════════════════════════════════ */

test("练手局①：practice 一路传到规则层（newState / start / debug.state 三处都认）", () => {
  assert.equal(R.newState({ practice: true }).cfg.practice, true, "newState 的 cfg 白名单里有 practice");
  assert.equal(R.newState({}).cfg.practice, false, "不传就是 false —— 默认绝不是练手局");
  const b = bootDom();
  assert.equal(b.B.start(b.host, {
    target: { id: "fang", name: "方姐", bond: 40 }, duration: 20, goal: 8, practice: true,
    onFinish: () => {},
  }), true, "练手局能正常开局（不再被任何门槛拦住）");
  const st = b.B.debug.state();
  assert.equal(st.practice, true, "debug.state() 里读得到 practice（真浏览器验收就靠它）");
  assert.equal(st.target.id, "fang", "对象正确");
  b.B.dispose();
});

test("练手局②：通过路径 —— 数值照常算，但 bondDelta 恒为 0，面板明确标注", () => {
  const b = bootDom();
  b.B.start(b.host, {
    target: { id: "su", name: "苏晚晴", bond: 40 }, duration: 75, goal: 8, practice: true,
    onFinish: () => {},
  });
  botRun(b.B);
  assert.equal(b.B.debug.state().win, true, "机器人真打出了通过");
  b.pump(3);
  const r = b.B.debug.state().result;
  assert.ok(r, "结算结果已产出");
  assert.equal(r.practice, true, "结果带 practice 标（页面层据此跳过落账）");
  assert.equal(r.bondDelta, 0, "练手局 bondDelta 必须是 0（同样表现本来该是 +6~+10）");
  assert.ok(r.served >= 8, "服务数照常算：" + r.served + "/" + r.goal);
  assert.ok(r.score > 0, "得分照常算：" + r.score);
  assert.ok(/练手局/.test(r.impact), "impact 换成练手局口径：" + r.impact);
  assert.ok(/练手局/.test(r.quota), "quota 换成练手局口径：" + r.quota);
  const panel = b.host.querySelector(".bf-result");
  const txt = String(panel._html || panel.innerHTML).replace(/<[^>]+>/g, " ").replace(/\s+/g, " ");
  assert.ok(/练手局\s*·\s*不影响好感/.test(txt), "结算面板顶部明确标注「练手局 · 不影响好感」");
  assert.ok(/不变（练手局）/.test(txt), "好感那一行写「不变（练手局）」（不是 +6）");
  const go = b.host.querySelector("#bfGo");
  assert.ok(go && /结束练手局/.test(go.textContent),
    "出口按钮文案 =「结束练手局 · 继续」（实际 " + (go && go.textContent) + "）");
  b.B.dispose();
});

test("练手局③：失败路径也不扣好感（bondDelta 仍是 0，不是 −3~−6）", () => {
  const b = bootDom();
  b.B.start(b.host, {
    target: { id: "guo", name: "陈果", bond: 30 }, duration: 20, goal: 8, practice: true,
    onFinish: () => {},
  });
  let g = 0;
  while (!b.B.debug.state().over && g++ < 20000) b.B.debug.tick(0.2);
  assert.equal(b.B.debug.state().win, false, "失败路径真跑出来了");
  b.pump(3);
  const r = b.B.debug.state().result;
  assert.equal(r.practice, true, "失败结果同样带 practice 标");
  assert.equal(r.bondDelta, 0, "练手局失败也不扣好感（本来该是 −3~−6）");
  assert.ok(/练手局/.test(r.impact), "impact 是练手局口径：" + r.impact);
  b.B.dispose();
});

test("练手局④：对照 —— 不带 practice 的正常局照旧结算（+6~+10，没被练手局改坏）", () => {
  const b = bootDom();
  b.B.start(b.host, {
    target: { id: "su", name: "苏晚晴", bond: 40 }, duration: 75, goal: 8,
    onFinish: () => {},
  });
  assert.equal(b.B.debug.state().practice, false, "正常局 practice = false");
  botRun(b.B);
  assert.equal(b.B.debug.state().win, true, "通过");
  b.pump(3);
  const r = b.B.debug.state().result;
  assert.equal(r.practice, false, "正常局结果不带 practice 标");
  assert.ok(r.bondDelta >= 6 && r.bondDelta <= 10, "正常局照旧 +6~+10：" + r.bondDelta);
  b.B.dispose();
});
